std::string FormatTerminalLink(const CliContext& ctx, const std::string& label,
                               const std::string& url) {
  if (label.empty()) {
    return {};
  }
  if (url.empty() || !ctx.is_tty) {
    return label;
  }
  return "\033]8;;" + url + "\a" + label + "\033]8;;\a";
}

